"use strict";(self.webpackChunkmy_til=self.webpackChunkmy_til||[]).push([["387"],{7017(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/05/29/ubuntu-tomcat-jenkins","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/05/29/ubuntu-tomcat-jenkins","source":"@site/blog/2026-05-29-ubuntu-tomcat-jenkins.md","title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.05.29","date":"2026-05-29T00:00:00.000Z","tags":[{"inline":true,"label":"Ubuntu","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ubuntu"},{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"Tomcat","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/tomcat"},{"inline":true,"label":"Jenkins","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/jenkins"},{"inline":true,"label":"Linux","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/linux"},{"inline":true,"label":"CI/CD","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ci-cd"}],"readingTime":3.42,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","date":"2026-05-29T00:00:00.000Z","tags":["Ubuntu","Java","Tomcat","Jenkins","Linux","CI/CD"]},"unlisted":false,"nextItem":{"title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/23/bootcamp-day01-OT"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.05.29\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n\uB85C\uCEEC\uC5D0\uC11C \uAC1C\uBC1C\uD55C \uC571\uC744 \uC2E4\uC81C \uC11C\uBC84\uC5D0 \uC62C\uB824\uC11C \uC678\uBD80\uC5D0\uC11C \uC811\uADFC \uAC00\uB2A5\uD558\uAC8C \uB9CC\uB4DC\uB294 \uC804\uCCB4 \uD750\uB984\uC744 \uC2E4\uC2B5\uD588\uB2E4.\\n\\n```\\nOS \uC900\uBE44 \u2192 Java \uC124\uCE58 \u2192 Tomcat 10 \u2192 systemd \uB4F1\uB85D \u2192 Jenkins CI/CD\\n(Ubuntu 22.04)  (OpenJDK 21)  (WAR \uBC30\uD3EC)  (\uC790\uB3D9 \uAE30\uB3D9)   (\uC790\uB3D9\uD654)\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uC11C\uBC84 \uAD6C\uCD95 \uAE30\uBC18 \u2014 OS\uC640 SSH\\n\\n\uC11C\uBC84\uB294 \uB85C\uCEEC IDE \uC2E4\uD589\uACFC \uB2E4\uB974\uB2E4. \uC678\uBD80 \uC0AC\uC6A9\uC790\uAC00 \uC811\uADFC \uAC00\uB2A5\uD55C \uD658\uACBD\uC774 \uB3FC\uC57C \uD558\uAE30 \uB54C\uBB38\uC5D0 OS \uC124\uCE58, \uB124\uD2B8\uC6CC\uD06C, \uAD8C\uD55C \uAD00\uB9AC\uAC00 \uC804\uBD80 \uC5EE\uC5EC\uC788\uB2E4.\\n\\n:::info \uD074\uB77C\uC6B0\uB4DC vs \uC628\uD504\uB808\uBBF8\uC2A4\\nAWS, Azure \uAC19\uC740 \uD074\uB77C\uC6B0\uB4DC\uB294 \uC778\uD504\uB77C(IaaS)\uB97C \uBE4C\uB9AC\uB294 \uAC83. \uBCF4\uC548 \uC694\uAD6C\uAC00 \uB192\uC740 \uAE30\uC5C5\uC740 \uC9C1\uC811 \uC11C\uBC84\uB97C \uAD6C\uCD95\uD558\uB294 \uC628\uD504\uB808\uBBF8\uC2A4\uB97C \uC120\uD0DD\uD558\uAE30\uB3C4 \uD55C\uB2E4. \uC624\uB298 \uC2E4\uC2B5\uC740 \uB85C\uCEEC PC\uB97C \uC11C\uBC84\uCC98\uB7FC \uC368\uC11C \uC628\uD504\uB808\uBBF8\uC2A4 \uD750\uB984\uC744 \uACBD\uD5D8\uD558\uB294 \uBC29\uC2DD\uC774\uC5C8\uB2E4.\\n:::\\n\\n### SSH \uD0A4 \uAE30\uBC18 \uC778\uC99D\\n\\nID/PW \uBC29\uC2DD\uBCF4\uB2E4 \uD0A4 \uAE30\uBC18 \uC778\uC99D\uC774 \uC548\uC804\uD558\uB2E4. \uACF5\uAC1C\uD0A4\uB294 \uC11C\uBC84\uC5D0, \uAC1C\uC778\uD0A4\uB294 \uD074\uB77C\uC774\uC5B8\uD2B8\uC5D0 \uBCF4\uAD00\uD55C\uB2E4.\\n\\n| \uB2E8\uACC4 | \uBA85\uB839\uC5B4 | \uBAA9\uC801 |\\n|------|--------|------|\\n| \uD0A4 \uC0DD\uC131 | `ssh-keygen -t rsa -b 4096` | \uACF5\uAC1C\uD0A4/\uAC1C\uC778\uD0A4 \uC30D \uC0DD\uC131 |\\n| \uD0A4 \uC704\uCE58 | `~/.ssh/id_rsa.pub` | \uACF5\uAC1C\uD0A4 \uC11C\uBC84\uC5D0 \uB4F1\uB85D |\\n| PPK \uBCC0\uD658 | PuTTYgen | PuTTY \uC811\uC18D\uC6A9 \uBCC0\uD658 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `IaaS` `\uC628\uD504\uB808\uBBF8\uC2A4` `LTS` `CLI` `SSH`\\n\\n---\\n\\n## 2\uFE0F\u20E3 OpenJDK 21 \uC124\uCE58\uC640 \uD658\uACBD\uBCC0\uC218\\n\\n\uC624\uB77C\uD074 JDK\uB294 \uAE30\uC5C5 \uD658\uACBD\uC5D0\uC11C \uC720\uB8CC(\uCF54\uC5B4\uB2F9 \uACFC\uAE08)\uAC00 \uB420 \uC218 \uC788\uC5B4\uC11C OpenJDK\uB97C \uC4F0\uB294 \uAC8C \uC77C\uBC18\uC801\uC774\uB2E4. Spring Boot 3.x\uB294 Java 17 \uC774\uC0C1\uC744 \uC694\uAD6C\uD558\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544\uC11C 21 LTS\uB97C \uC120\uD0DD\uD588\uB2E4.\\n\\n```bash\\n# \uD328\uD0A4\uC9C0 \uBAA9\uB85D \uC5C5\uB370\uC774\uD2B8 \uD6C4 \uC124\uCE58\\napt update && apt upgrade\\napt install openjdk-21-jdk\\n\\n# \uC124\uCE58 \uD655\uC778\\njava -version\\nfind / -name java\\n```\\n\\n### \uD658\uACBD\uBCC0\uC218 \uC124\uC815 \u2014 /etc/profile vs /etc/environment\\n\\n| \uD30C\uC77C | \uBAA9\uC801 | \uD615\uC2DD |\\n|------|------|------|\\n| `/etc/profile` | \uC258 \uC2DC\uC791 \uC2DC \uC804\uC5ED \uC124\uC815 | `export` \uC0AC\uC6A9, PATH \uD655\uC7A5\uC5D0 \uC801\uD569 |\\n| `/etc/environment` | \uC2DC\uC2A4\uD15C \uC804\uC5ED \uBCC0\uC218 \uC120\uC5B8 | `export` \uC5C6\uC774 `KEY=\\"VALUE\\"` |\\n\\n```bash\\n# \uC124\uC815 \uC989\uC2DC \uBC18\uC601\\nsource /etc/profile\\nsource /etc/environment\\n\\n# \uC801\uC6A9 \uD655\uC778\\necho $JAVA_HOME\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `OpenJDK` `JAVA_HOME` `PATH` `source` `Vim`\\n\\n---\\n\\n## 3\uFE0F\u20E3 Tomcat 10 \uC218\uB3D9 \uC124\uCE58\uC640 WAR \uBC30\uD3EC\\n\\n`apt`\uB85C \uC124\uCE58 \uAC00\uB2A5\uD55C \uBC84\uC804\uACFC \uC2E4\uC81C \uD544\uC694\uD55C \uBC84\uC804\uC774 \uB2E4\uB97C \uC218 \uC788\uC5B4\uC11C, \uC2E4\uBB34\uC5D0\uC11C\uB294 `tar.gz`\uB85C \uC9C1\uC811 \uC124\uCE58\uD55C\uB2E4.\\n\\n### \uC124\uCE58 \uC808\uCC28\\n\\n1. `wget`\uC73C\uB85C tar.gz \uB2E4\uC6B4\uB85C\uB4DC \uD6C4 `/tmp`\uC5D0 \uC555\uCD95 \uD574\uC81C\\n2. `/usr/local/tomcat10`\uC73C\uB85C \uC774\uB3D9 (\uC2E4\uD589\uD30C\uC77C\uC740 `/usr` \uACC4\uC5F4)\\n3. `chmod -R 755`\uC73C\uB85C \uD558\uC704\uAE4C\uC9C0 \uC2E4\uD589 \uAD8C\uD55C \uBD80\uC5EC\\n4. `CATALINA_HOME` \uD658\uACBD\uBCC0\uC218 \uC124\uC815\\n5. `tomcat-users.xml`\uC5D0\uC11C \uAD00\uB9AC\uC790 \uACC4\uC815 \uCD94\uAC00\\n6. `context.xml`\uC5D0\uC11C RemoteAddrValve \uC8FC\uC11D \uCC98\uB9AC (\uC678\uBD80 \uC811\uADFC \uD5C8\uC6A9)\\n\\n:::warning\\n`context.xml`\uC758 RemoteAddrValve \uC81C\uD55C \uD574\uC81C\uB294 \uBCF4\uC548\uC0C1 \uBBFC\uAC10\uD55C \uC124\uC815\uC774\uB2E4. \uC2E4\uBB34\uC5D0\uC11C\uB294 IP \uC81C\uD55C\uC744 \uC720\uC9C0\uD558\uACE0 \uD5C8\uC6A9 \uB300\uC0C1\uC744 \uCD5C\uC18C\uD654\uD558\uB294 \uAC8C \uC77C\uBC18\uC801\uC774\uB2E4.\\n:::\\n\\n```bash\\n# \uAE30\uB3D9 / \uC885\uB8CC\\n./bin/startup.sh\\n./bin/shutdown.sh\\n\\n# \uAE30\uB3D9 \uD655\uC778\\ncurl http://localhost:8080\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Tomcat` `CATALINA_HOME` `tomcat-users.xml` `context.xml` `WAR`\\n\\n---\\n\\n## 4\uFE0F\u20E3 systemd\uB85C Tomcat \uC11C\uBE44\uC2A4 \uB4F1\uB85D\\n\\n\uC218\uB3D9 \uC2E4\uD589\uC740 \uC11C\uBC84 \uC7AC\uBD80\uD305 \uD6C4 \uB9E4\uBC88 \uC0AC\uB78C\uC774 \uAE30\uB3D9\uD574\uC57C \uD574\uC11C \uC6B4\uC601\uC5D0 \uBD80\uC801\uD569\uD558\uB2E4. systemd\uC5D0 \uB4F1\uB85D\uD558\uBA74 \uBD80\uD305 \uC2DC \uC790\uB3D9 \uAE30\uB3D9\uB41C\uB2E4.\\n\\n### \uC11C\uBE44\uC2A4 \uC804\uC6A9 \uACC4\uC815 \uB9CC\uB4E4\uAE30\\n\\n```bash\\n# \uADF8\uB8F9 \uBC0F nologin \uACC4\uC815 \uC0DD\uC131\\ngroupadd tomcat\\nuseradd -s /bin/nologin -g tomcat -d /usr/local/tomcat10 tomcat\\n\\n# \uC18C\uC720\uAD8C \uC774\uC804 (chmod: \uAD8C\uD55C\uBE44\uD2B8 \uBCC0\uACBD / chown: \uC18C\uC720\uC790 \uBCC0\uACBD)\\nchown -PR tomcat:tomcat /usr/local/tomcat10\\n```\\n\\n:::info\\n`nologin` \uACC4\uC815\uC740 \uB300\uD654\uD615 \uB85C\uADF8\uC778\uC774 \uBD88\uAC00\uB2A5\uD55C \uC11C\uBE44\uC2A4 \uC804\uC6A9 \uACC4\uC815\uC774\uB2E4. \uBCF4\uC548\uC744 \uC704\uD574 \uC11C\uBE44\uC2A4\uB294 \uC804\uC6A9 \uACC4\uC815\uC73C\uB85C \uC2E4\uD589\uD55C\uB2E4.\\n:::\\n\\n### \uC11C\uBE44\uC2A4 \uD30C\uC77C \uD575\uC2EC \uAD6C\uC131\\n\\n| \uD56D\uBAA9 | \uC758\uBBF8 |\\n|------|------|\\n| `User, Group` | \uC11C\uBE44\uC2A4 \uC2E4\uD589 \uACC4\uC815/\uADF8\uB8F9 (tomcat) |\\n| `Environment` | JAVA_HOME, CATALINA_HOME \uACBD\uB85C |\\n| `ExecStart/ExecStop` | \uAE30\uB3D9/\uC885\uB8CC \uC2A4\uD06C\uB9BD\uD2B8 \uC5F0\uACB0 |\\n| `WantedBy` | `multi-user.target` (\uBD80\uD305 \uB2E8\uACC4 \uC5F0\uACB0) |\\n\\n```bash\\n# \uC11C\uBE44\uC2A4 \uB4F1\uB85D \uBC0F \uAD00\uB9AC\\nsystemctl daemon-reload\\nsystemctl enable tomcat10.service\\nsystemctl start tomcat10.service\\nsystemctl status tomcat10.service\\n\\n# \uD3EC\uD2B8 \uC810\uC720 \uD655\uC778 (-l \uB9AC\uC2A4\uB2DD -n \uC22B\uC790 -t TCP -p \uD504\uB85C\uC138\uC2A4)\\nss -lntp\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `systemd` `systemctl` `useradd` `chown` `ss`\\n\\n---\\n\\n## 5\uFE0F\u20E3 Jenkins \uC124\uCE58\uC640 \uD3EC\uD2B8 \uCDA9\uB3CC \uD574\uACB0\\n\\nJenkins\uB294 Git push \uC774\uBCA4\uD2B8\uB97C \uBC1B\uC544 \uC18C\uC2A4 \uCCB4\uD06C\uC544\uC6C3 \u2192 \uBE4C\uB4DC \u2192 \uBC30\uD3EC\uB97C \uC790\uB3D9\uD654\uD558\uB294 CI \uC11C\uBC84\uB2E4. \uC124\uCE58 \uD6C4 Tomcat(8080)\uACFC \uD3EC\uD2B8 \uCDA9\uB3CC\uC774 \uBC1C\uC0DD\uD574\uC11C 8181\uB85C \uBCC0\uACBD\uD588\uB2E4.\\n\\n```\\nGit push \u2192 (webhook) \u2192 Jenkins \u2192 (Maven \uBE4C\uB4DC) \u2192 WAR \uC0DD\uC131 \u2192 Tomcat \uBC30\uD3EC \u2192 \uC11C\uBE44\uC2A4\\n```\\n\\n### \uD3EC\uD2B8 \uCDA9\uB3CC \uD574\uACB0 \uD3EC\uC778\uD2B8\\n\\n:::danger \uD575\uC2EC\\n`/etc/default/jenkins`\uC640 systemd \uC11C\uBE44\uC2A4 \uD30C\uC77C **\uB450 \uACF3 \uBAA8\uB450** \uD3EC\uD2B8\uB97C \uC77C\uCE58\uC2DC\uCF1C\uC57C \uD55C\uB2E4. \uD55C \uACF3\uB9CC \uBC14\uAFB8\uBA74 \uC801\uC6A9\uC774 \uC548 \uB41C\uB2E4.\\n:::\\n\\n```bash\\n# \uB450 \uACF3 \uB2E4 8181\uB85C \uBCC0\uACBD \uD544\uC694\\n# 1. /etc/default/jenkins \u2192 HTTP_PORT=8181\\n# 2. jenkins.service \u2192 JENKINS_PORT=8181\\n\\nsystemctl daemon-reload\\nsystemctl start jenkins\\nsystemctl status jenkins\\n```\\n\\n### Jenkins \uCD08\uAE30 \uC124\uC815 \uC21C\uC11C\\n\\n1. `http://localhost:8181` \uC811\uC18D\\n2. `cat <initialAdminPassword \uACBD\uB85C>` \uB85C \uCD08\uAE30 \uBE44\uBC88 \uD655\uC778\\n3. Install suggested plugins \uC120\uD0DD\\n4. \uAD00\uB9AC\uC790 \uACC4\uC815 \uC0DD\uC131 (\uAF2D \uD574\uC57C \uC774\uD6C4 \uC124\uC815\uC774 \uD3B8\uD568)\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Jenkins` `CI` `\uD3EC\uD2B8 \uCDA9\uB3CC` `systemd` `GitHub Actions`\\n\\n---\\n\\n## \u{1F51C} \uB2E4\uC74C\uC5D0 \uC774\uC5B4\uC9C8 \uB0B4\uC6A9\\n\\n\uC624\uB298 Jenkins \uCD08\uAE30 \uC124\uC815 \uD654\uBA74\uAE4C\uC9C0 \uC9C4\uD589\uD588\uACE0, \uB2E4\uC74C\uC5D0\uB294 \uC774\uAC78 \uC774\uC5B4\uC11C \uC9C4\uD589\uD560 \uC608\uC815\uC774\uB2E4.\\n\\n- Docker \uC124\uCE58\\n- ngrok\uC73C\uB85C \uC678\uBD80 \uC811\uADFC (\uD3EC\uD2B8\uD3EC\uC6CC\uB529 \uB300\uCCB4)\\n- Git \uC5F0\uB3D9 \u2192 CI/CD \uD30C\uC774\uD504\uB77C\uC778 \uC644\uC131"},{"id":"/2026/02/23/bootcamp-day01-OT","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/23/bootcamp-day01-OT","source":"@site/blog/2026-02-23-bootcamp-day01-OT.md","title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.05.29","date":"2026-02-23T00:00:00.000Z","tags":[{"inline":true,"label":"\uBD80\uD2B8\uCEA0\uD504","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uBD80\uD2B8\uCEA0\uD504"},{"inline":true,"label":"KDT","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/kdt"},{"inline":true,"label":"OT","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ot"},{"inline":true,"label":"\uCD9C\uACB0","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uCD9C\uACB0"},{"inline":true,"label":"\uCDE8\uC5C5\uC9C0\uC6D0","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uCDE8\uC5C5\uC9C0\uC6D0"}],"readingTime":4.59,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","date":"2026-02-23T00:00:00.000Z","tags":["\uBD80\uD2B8\uCEA0\uD504","KDT","OT","\uCD9C\uACB0","\uCDE8\uC5C5\uC9C0\uC6D0"]},"unlisted":false,"prevItem":{"title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/05/29/ubuntu-tomcat-jenkins"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.05.29\\n\\n## \u{1F5FA} \uC624\uB298 \uB2E4\uB8EC \uB0B4\uC6A9 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uD074\uB798\uC2A4\uB8F8/\uD074\uB798\uC2A4\uCC57 \u2192 QR \uCD9C\uACB0 \uCCB4\uACC4 \u2192 \uC9C0\uAC01/\uC870\uD1F4/\uC678\uCD9C \uADDC\uCE59\\n\u2192 \uACF5\uACB0/\uC815\uC815 \uC808\uCC28 \u2192 \uC81C\uC801\xb7\uC218\uB8CC \uAE30\uC900 \u2192 \uCEE4\uB9AC\uC5B4 OT \u2192 \uCDE8\uC5C5\uC9C0\uC6D0 \uD504\uB85C\uADF8\uB7A8\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uD074\uB798\uC2A4\uB8F8 & \uD074\uB798\uC2A4\uCC57 \uC6B4\uC601 \uAD6C\uC870\\n\\n\uC218\uC5C5 \uAD00\uB828 \uCC44\uB110\uC740 \uD074\uB798\uC2A4\uCC57 \uAE30\uBC18\uC73C\uB85C \uC6B4\uC601\uB41C\uB2E4. \uCC98\uC74C \uC811\uC18D\uD558\uBA74 `general`\uB9CC \uBCF4\uC774\uB294\uB370, \uC88C\uCE21 \uD558\uB2E8 **\uB514\uB809\uD1A0\uB9AC**\uC5D0\uC11C \uCC44\uB110\uC744 \uCC3E\uC544 `\uCC38\uC5EC` \uBC84\uD2BC\uC73C\uB85C \uCD94\uAC00\uD574\uC57C \uD55C\uB2E4.\\n\\n| \uAD6C\uBD84 | \uCC44\uB110 | \uBAA9\uC801 |\\n|------|------|------|\\n| \uACF5\uC9C0 | \uACF5\uC9C0\uC0AC\uD56D | \uC77C\uC815, \uD544\uB3C5 \uC548\uB0B4 (\uD074\uB798\uC2A4\uB8F8/\uCC57 \uB3D9\uC77C) |\\n| \uC218\uC5C5 Q&A | \uAC15\uC758 \uC911 \uCC44\uB110 (\uC2A4\uB808\uB4DC) | \uC218\uC5C5 \uD750\uB984 \uC720\uC9C0\uD558\uBA70 \uC9C8\uBB38 |\\n| \uC6B4\uC601 Q&A | \uBB34\uC5C7\uC774\uB4E0 \uBB3C\uC5B4\uBCF4\uC138\uC694 | \uD589\uC815/\uC6B4\uC601 \uC804\uBC18 \uBB38\uC758 |\\n| \uCD9C\uACB0 \uBCF4\uC870 | QR \uC694\uCCAD\uBC29 | QR \uBBF8\uB178\uCD9C \uC2DC\uAC04 \uC694\uCCAD |\\n\\n:::info\\n**AI \uB178\uD2B8** \uAE30\uB2A5: \uC218\uC5C5 \uB2E4\uC74C\uB0A0 \uC694\uC57D\uBCF8\uC774 \uC790\uB3D9 \uC0DD\uC131\uB418\uC5B4 \uBCF5\uC2B5\uC5D0 \uD65C\uC6A9 \uAC00\uB2A5\uD558\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD074\uB798\uC2A4\uCC57` `\uB514\uB809\uD1A0\uB9AC` `\uC2A4\uB808\uB4DC` `\uACF5\uC9C0\uC0AC\uD56D` `AI\uB178\uD2B8`\\n\\n---\\n\\n## 2\uFE0F\u20E3 \uAD50\uC721 \uC6B4\uC601 \uADDC\uC815\\n\\n- \uC218\uC5C5 \uC2DC\uAC04: 09:00 ~ 18:00 (50\uBD84 \uC218\uC5C5 + 10\uBD84 \uD734\uC2DD)\\n- \uC810\uC2EC: 11:50 ~ 13:00 (\uAC15\uC0AC \uC7AC\uB7C9\uC73C\uB85C \uC720\uB3D9)\\n- \uAC1C\uAC15\uC77C/\uC885\uAC15\uC77C: 14:00 ~ 18:00 \uBCC4\uB3C4 \uC6B4\uC601\\n- \uACF5\uD734\uC77C \uD734\uAC15\\n\\n### \uCE74\uBA54\uB77C \uCD9C\uC11D \uADDC\uC815\\n\\n**\uCE74\uBA54\uB77C ON\uC774 \uCD9C\uC11D\uC758 \uD575\uC2EC \uC804\uC81C\uB2E4.** \uC5BC\uAD74(\uB208, \uCF54, \uC785)\uC774 \uC2DD\uBCC4 \uAC00\uB2A5\uD574\uC57C \uCD9C\uC11D\uC73C\uB85C \uC778\uC815\uB41C\uB2E4.\\n\\n:::warning\\n\uC778\uD130\uB137 \uC7AC\uC5F0\uACB0 \uC2DC \uCE74\uBA54\uB77C\uAC00 \uAEBC\uC9C8 \uC218 \uC788\uC5B4 \uC218\uC2DC\uB85C \uD655\uC778\uD574\uC57C \uD55C\uB2E4.\\n:::\\n\\n| \uC6B4\uC601 \uD56D\uBAA9 | \uAE30\uC900 | \uC8FC\uC758\uC810 |\\n|----------|------|--------|\\n| \uCE74\uBA54\uB77C \uCD9C\uC11D | \uC5BC\uAD74 \uC2DD\uBCC4 \uAC00\uB2A5 \uD544\uC218 | \uC7AC\uC5F0\uACB0 \uD6C4 \uCE74\uBA54\uB77C \uAEBC\uC9D0 \uC8FC\uC758 |\\n| \uBB34\uB2E8\uC774\uD0C8 | 15\uBD84 \uC774\uC0C1 \uC774\uD0C8 \uB610\uB294 \uCE74\uBA54\uB77C OFF | \uC7A0\uAE50 \uC774\uB3D9\uB3C4 \uC678\uCD9C \uC808\uCC28 \uD544\uC694 |\\n| \uD68C\uACE0 (16~18\uC2DC) | \uC218\uC5C5 \uC2DC\uAC04\uC73C\uB85C \uAC04\uC8FC | \uD68C\uACE0 \uC911\uC5D0\uB3C4 \uCE74\uBA54\uB77C ON |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uCE74\uBA54\uB77C\uC628` `\uD68C\uACE0` `\uC8FC\uAC04\uC124\uBB38` `\uBB34\uB2E8\uC774\uD0C8` `\uD559\uC2B5\uAE30\uB85D`\\n\\n---\\n\\n## 3\uFE0F\u20E3 QR \uCD9C\uACB0 \uCCB4\uACC4\\n\\n\uCD9C\uACB0\uC740 **\uBA38\uC0ACA** \uC571\uC5D0\uC11C QR \uCCB4\uD06C + \uAC15\uC758\uC2E4 \uC785\uC7A5 \uB450 \uAC00\uC9C0\uB97C \uBAA8\uB450 \uC644\uB8CC\uD574\uC57C \uD55C\uB2E4.\\n\\n:::danger \uC911\uC694\\n\\"\uCCB4\uD06C \uC644\uB8CC\\" \uBB38\uAD6C\uAC00 \uB5A0\uB3C4 \uC2E4\uC81C \uC2DC\uAC04\uC774 \uAE30\uB85D\uB410\uB294\uC9C0 \uBC18\uB4DC\uC2DC \uD655\uC778! \uC804\uC0B0 \uC624\uB958\uB85C \uB204\uB77D\uB418\uB294 \uC0AC\uB840\uAC00 \uC788\uACE0, \uBBF8\uD655\uC778\uC740 \uBCF8\uC778 \uBD80\uC8FC\uC758\uB85C \uCC98\uB9AC\uB41C\uB2E4.\\n:::\\n\\n| \uD56D\uBAA9 | \uC2DC\uAC04 \uCC3D | \uBE44\uACE0 |\\n|------|---------|------|\\n| \uC785\uC2E4 QR | 08:50 ~ 09:10 | \uCC3D \uC678\uC5D0\uB294 \uBA58\uD1A0\uC5D0\uAC8C \uC694\uCCAD |\\n| \uD1F4\uC2E4 QR | 17:50 ~ 18:30 | \uC218\uC5C5 \uC9C0\uC5F0 \uACE0\uB824\uD574 \uAE38\uAC8C \uC5F4\uB9BC |\\n| \uC0C1\uC2DC QR | \uACE0\uC815 \uCC3D \uC678 | \uC694\uCCAD\uBC29 \uC591\uC2DD\uC73C\uB85C \uC2E0\uCCAD |\\n\\n:::danger\\n**\uD574\uC678\uC5D0\uC11C QR \uCD9C\uC11D = \uBD80\uC815 \uCD9C\uACB0 = \uC989\uC2DC \uC81C\uC801** (\uCCAD\uAC15\uC740 \uAC00\uB2A5\uD558\uC9C0\uB9CC QR \uCCB4\uD06C\uB294 \uC808\uB300 \uC548 \uB428)\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `QR\uCCB4\uD06C` `\uAC15\uC758\uC2E4\uC785\uC7A5` `\uC785\uD1F4\uC2E4\uC2DC\uAC04\uD655\uC778` `\uC0C1\uC2DCQR` `\uD574\uC678\uCD9C\uC11D\uAE08\uC9C0`\\n\\n---\\n\\n## 4\uFE0F\u20E3 \uC9C0\uAC01 / \uC870\uD1F4 / \uC678\uCD9C / \uACB0\uC11D \uADDC\uCE59\\n\\n### \uD575\uC2EC: 50% \uADDC\uCE59\\n\\n\uD558\uB8E8 \uC218\uC5C5\uC758 **50% \uBBF8\uB9CC \uC218\uAC15 = \uACB0\uC11D** \uCC98\uB9AC\uB41C\uB2E4.\\n\\n| \uAD6C\uBD84 | \uC778\uC815 \uC870\uAC74 | \uC8FC\uC758\uC810 |\\n|------|----------|--------|\\n| \uACB0\uC11D | QR \uBBF8\uCCB4\uD06C or 50% \uBBF8\uB9CC \uC218\uAC15 | \uC77C\uBD80 \uCC38\uC5EC\uD574\uB3C4 \uACB0\uC11D \uB420 \uC218 \uC788\uC74C |\\n| \uC9C0\uAC01 | \uC2DC\uC791 \uD6C4 50% \uC774\uB0B4 \uC785\uC2E4 | QR\uB9CC \uCC0D\uACE0 \uC785\uC2E4 \uB2A6\uC73C\uBA74 \uC9C0\uAC01 |\\n| \uC870\uD1F4 | 50% \uC774\uC0C1 \uC218\uAC15 \uD6C4 \uC911\uAC04 \uD1F4\uC2E4 | 50% \uBBF8\uB9CC\uC774\uBA74 \uACB0\uC11D \uCC98\uB9AC |\\n| \uC678\uCD9C | \uC678\uCD9C QR \u2192 \uBCF5\uADC0 QR \uC808\uCC28 \uC644\uB8CC | \uB450 QR \uBAA8\uB450 \uCC0D\uC5B4\uC57C \uD568 |\\n\\n### \uB204\uC801 \uADDC\uCE59\\n\\n:::warning\\n\uC9C0\uAC01 + \uC870\uD1F4 + \uC678\uCD9C **\uAC01\uAC01 3\uD68C \uB204\uC801 = \uACB0\uC11D 1\uD68C**\\n\\n\uD558\uB8E8\uC5D0 \uC9C0\uAC01 + \uC678\uCD9C + \uC870\uD1F4 \uBAA8\uB450 \uD558\uBA74 \u2192 \uD558\uB8E8\uC5D0 3\uD68C \uB204\uC801 \uAC00\uB2A5\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `50%\uADDC\uCE59` `\uC9C0\uAC01` `\uC870\uD1F4` `\uC678\uCD9C` `\uB204\uC8013\uD68C\uACB0\uC11D`\\n\\n---\\n\\n## 5\uFE0F\u20E3 \uACF5\uACB0(\uCD9C\uC11D \uC778\uC815) & \uCD9C\uACB0 \uC815\uC815\\n\\n### \uACF5\uACB0 \uAC00\uB2A5 \uC0AC\uC720\\n\\n\uAD6D\uAC00\uC2DC\uD5D8, \uC608\uBE44\uAD70/\uBBFC\uBC29\uC704, \uC9C8\uBCD1/\uC785\uC6D0, \uACBD\uC870\uC0AC, \uBA74\uC811 \uB4F1\\n\\n:::warning\\n**\uC9C8\uBCD1 \uACF5\uACB0\uC740 \uD6C8\uB828\uC77C\uC218\uC758 10%\uAE4C\uC9C0\uB9CC \uAC00\uB2A5** (121\uC77C \uACFC\uC815 \uAE30\uC900 \uC57D 12\uD68C)\\n\\n\uCD08\uBC18\uC5D0 \uACBD\uBBF8\uD55C \uC0AC\uC720\uB85C \uC18C\uC9C4\uD558\uBA74 \uB098\uC911\uC5D0 \uBABB \uC500 \u2014 \uC804\uB7B5\uC801\uC73C\uB85C \uC0AC\uC6A9\uD560 \uAC83\\n:::\\n\\n### \uC99D\uBE59 \uC11C\uB958 \uC694\uAC74\\n\\n| \uACF5\uACB0 \uC720\uD615 | \uD544\uC218 \uC11C\uB958 | \uD575\uC2EC \uC694\uAC74 |\\n|----------|----------|----------|\\n| \uC9C8\uBCD1/\uC785\uC6D0 | \uC9C4\uB8CC\uD655\uC778\uC11C + \uCC98\uBC29\uC804 + \uACB0\uC81C\uC601\uC218\uC99D | **\uC9C8\uBCD1\uCF54\uB4DC \uAE30\uC7AC \uD544\uC218** |\\n| \uBA74\uC811 | \uB0A0\uC778\uB41C \uBA74\uC811\uD655\uC778\uC11C + \uC5F0\uB77D\uB0B4\uC5ED + \uAD6C\uC778\uACF5\uACE0 | \uAE30\uC5C5 \uD655\uC778 \uC804\uD654 \uC62C \uC218 \uC788\uC74C |\\n\\n:::danger\\n\uBBF8\uC6A9, \uAC74\uAC15\uAC80\uC9C4, \uC2A4\uCF00\uC77C\uB9C1 \u2192 \uC9C8\uBCD1 \uACF5\uACB0 \uBD88\uC778\uC815\\n:::\\n\\n- \uC81C\uCD9C \uAE30\uD55C: \uC0AC\uC720 \uBC1C\uC0DD \uD6C4 **3\uC77C \uC774\uB0B4**\\n- \uC2E0\uCCAD \uC704\uCE58: **\uAD50\uC721\uD589\uC815 \uB514\uC2A4\uCF54\uB4DC** (\uD504\uB85C\uD544 \uC2E4\uBA85 \uC124\uC815 \uD544\uC218)\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uACF5\uACB0\uC2E0\uCCAD` `\uC9C8\uBCD1\uCF54\uB4DC` `\uC99D\uBE59\uC11C\uB958` `\uC81C\uCD9C\uAE30\uD55C` `\uAD50\uC721\uD589\uC815\uB514\uC2A4\uCF54\uB4DC`\\n\\n---\\n\\n## 6\uFE0F\u20E3 \uC218\uAC15 \uC7A5\uC18C \uADDC\uC815\\n\\n\uC624\uC804/\uC624\uD6C4 QR\uC740 \uB3D9\uC77C\uD55C \uC7A5\uC18C\uC5D0\uC11C \uCC0D\uB294 \uAC8C \uC6D0\uCE59. \uBD88\uAC00\uD53C\uD558\uAC8C \uC774\uB3D9\uD560 \uACBD\uC6B0 **\uC7A5\uC18C \uC774\uB3D9 \uD655\uC778\uC11C** \uC0AC\uC804 \uC81C\uCD9C \uD544\uC218.\\n\\n| \uACF5\uAC04 \uC720\uD615 | \uAC00\uB2A5 \uC5EC\uBD80 | \uC774\uC720 |\\n|----------|----------|------|\\n| 1\uC778 \uB8F8\uCE74\uD398 / 1\uC778 \uC2A4\uD130\uB514\uB8F8 | \u2705 \uC870\uAC74\uBD80 \uAC00\uB2A5 | \uC18C\uC74C \uD1B5\uC81C, \uB2E8\uB3C5 \uACF5\uAC04 |\\n| \uB3C5\uC11C\uC2E4 | \u2705 \uBE44\uAD50\uC801 \uAC00\uB2A5 | \uACE0\uC815 \uC88C\uC11D, \uC800\uC18C\uC74C |\\n| \uB3C4\uC11C\uAD00 | \u26A0\uFE0F \uC9C0\uC591 | \uC624\uD508 \uACF5\uAC04, \uC774\uB3D9 \uC778\uC6D0 \uB178\uCD9C |\\n| \uC77C\uBC18 \uCE74\uD398/\uC74C\uC2DD\uC810 | \u274C \uBD88\uAC00\uC5D0 \uAC00\uAE4C\uC6C0 | \uBD80\uC815 \uCD9C\uACB0 \uD310\uB2E8 \uAC00\uB2A5\uC131 \uD07C |\\n\\n:::warning\\n\uC7A5\uC18C \uC774\uB3D9\uC740 **\uC26C\uB294 \uC2DC\uAC04 / \uC810\uC2EC\uC2DC\uAC04\uC5D0\uB9CC** \uAC00\uB2A5. \uC218\uC5C5 \uC911 \uC774\uB3D9 = \uBB34\uB2E8\uC774\uD0C8\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC7A5\uC18C\uC774\uB3D9\uD655\uC778\uC11C` `\uC26C\uB294\uC2DC\uAC04\uC774\uB3D9` `\uC624\uD508\uACF5\uAC04\uC81C\uD55C` `\uBD80\uC815\uCD9C\uACB0` `\uC218\uAC15\uD658\uACBD`\\n\\n---\\n\\n## 7\uFE0F\u20E3 \uC81C\uC801 & \uC218\uB8CC \uAE30\uC900\\n\\n### \uC218\uB8CC \uC870\uAC74\\n\\n- **\uCD9C\uC11D\uB960 80% \uC774\uC0C1** + **\uD504\uB85C\uC81D\uD2B8 \uACB0\uACFC\uBB3C** \uD544\uC218\\n- \uACB0\uC11D\uC774 \uC804\uCCB4\uC758 20% \uCD08\uACFC \uC2DC \uC81C\uC801 \uB300\uC0C1\\n\\n### \uACBD\uACE0 \uB2E8\uACC4\\n\\n1\uCC28 \uC11C\uBA74 \uACBD\uACE0 \u2192 2\uCC28 \uC0C1\uB2F4 + \uD655\uC778\uC11C/\uC11C\uC57D\uC11C \u2192 3\uCC28 \uAC1C\uC120 \uBBF8\uD761 \uC2DC **\uC81C\uC801**\\n\\n:::danger\\n**\uBD80\uC815 \uCD9C\uACB0\uC740 \uD69F\uC218 \uBB34\uAD00 \uC989\uC2DC \uC81C\uC801**\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC218\uB8CC80%` `\uC81C\uC801\uAE30\uC900` `\uBD80\uC815\uCD9C\uACB0` `\uACBD\uACE0\uC81C\uB3C4` `\uD504\uB85C\uC81D\uD2B8\uACB0\uACFC\uBB3C`\\n\\n---\\n\\n## 8\uFE0F\u20E3 \uD6C8\uB828\uC7A5\uB824\uAE08 & \uD589\uC815 \uCC98\uB9AC\\n\\n- \uC9C0\uAE09 \uC870\uAC74: \uB2E8\uC704\uAE30\uAC04 **\uCD9C\uC11D 80% \uC774\uC0C1** + **HRD \uC218\uAC15\uD3C9 \uC791\uC131** (\uC885\uAC15 \uD6C4 1\uAC1C\uC6D4 \uC774\uB0B4)\\n- \uC9C0\uAE09\uC561: 1\uC77C 1\uB9CC5\uCC9C\uC6D0 \uAE30\uC900, **\uC6D4 \uCD5C\uB300 30\uB9CC\uC6D0** \uC0C1\uD55C\\n- \uACC4\uC88C \uD655\uC778: **\uACE0\uC6A924**\uC5D0\uC11C \uBCF8\uC778 \uB4F1\uB85D \uACC4\uC88C \uD655\uC778 \uD544\uC218\\n\\n:::warning\\n\uC218\uC5C5 \uC2DC\uAC04\uACFC \uACB9\uCE58\uB294 \uADFC\uB85C\uB294 \uBD88\uAC00. \uADFC\uB85C \uC911 QR \uCD9C\uC11D = \uBD80\uC815 \uCD9C\uACB0\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD6C8\uB828\uC7A5\uB824\uAE08` `\uACE0\uC6A9\uD615\uD0DC\uBCC0\uACBD` `\uACE0\uC6A924` `HRD\uC218\uAC15\uD3C9` `\uC11C\uB958\uC694\uCCAD`\\n\\n---\\n\\n## 9\uFE0F\u20E3 \uCEE4\uB9AC\uC5B4 OT \u2014 \uBAA9\uD45C \uC218\uCE58\uD654\\n\\n\uCDE8\uC5C5 \uC900\uBE44\uB294 \uC624\uB298\uBD80\uD130 \uC2DC\uC791\uC774\uB77C\uB294 \uAD00\uC810\uC73C\uB85C \uC9C4\uD589\uB410\uB2E4. \uD575\uC2EC\uC740 **\uBAA9\uD45C\uB97C \uC218\uCE58\uD654**\uD558\uB294 \uAC83.\\n\\n| \uB098\uC05C \uC608 | \uC88B\uC740 \uC608 |\\n|---------|---------|\\n| \uBE14\uB85C\uADF8 \uC4F0\uAE30 | \uC8FC 3\uD68C \uAE30\uC220 \uAE00 1\uD3B8 \uBC1C\uD589 |\\n| \uC774\uB825\uC11C \uC4F0\uAE30 | \uC218\uB8CC 2\uB2EC \uC804 \uCD08\uC548 \uC644\uC131 + \uCCA8\uC0AD 3\uD68C \uC774\uC0C1 |\\n| \uCF54\uD14C \uC900\uBE44\uD558\uAE30 | \uC8FC 3\uD68C \uBB38\uC81C \uD480\uACE0 \uC624\uB2F5 \uC815\uB9AC |\\n| \uD504\uB85C\uC81D\uD2B8 \uD574\uBCF4\uAE30 | \uD504\uB85C\uC81D\uD2B8 2\uAC1C \uAD6C\uC131 + \uBC30\uD3EC\uAE4C\uC9C0 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD22C\uB450\uB9AC\uC2A4\uD2B8` `\uAC1C\uC778\uCC4C\uB9B0\uC9C0` `\uD300\uCC4C\uB9B0\uC9C0` `\uBAA9\uD45C\uC218\uCE58\uD654` `\uC18C\uADF8\uB8F9\uD65C\uB3D9`\\n\\n---\\n\\n## \u{1F51F} \uCDE8\uC5C5\uC9C0\uC6D0 \uD504\uB85C\uADF8\uB7A8\\n\\n| \uD504\uB85C\uADF8\uB7A8 | \uB0B4\uC6A9 |\\n|---------|------|\\n| \uC138\uB81D\uAC8C\uD2F0 \uCEE4\uBBA4\uB2C8\uD2F0 | \uB514\uC2A4\uCF54\uB4DC \uAE30\uBC18 \uCDE8\uC5C5 \uC815\uBCF4 + \uD611\uC57D \uAE30\uC5C5 \uACF5\uACE0 |\\n| 1:1 \uC0C1\uB2F4/\uCCA8\uC0AD | \uC774\uB825\uC11C, \uC790\uC18C\uC11C, \uBA74\uC811, \uD3EC\uD2B8\uD3F4\uB9AC\uC624 \uCF54\uCE6D |\\n| \uBA38\uC0AC \uB85C\uCF13\uB2E8 | \uC778\uD134\uC2ED\uD615 \uC2E4\uBB34 \uACBD\uD5D8 (\uC8FC5\uC77C, \uC77C3\uC2DC\uAC04, 4\uC8FC) |\\n| \uB2E8\uAE30 \uADFC\uBB34 | \uB3D9\uC77C \uC9C1\uC885 \uACBD\uB825 \uC778\uC815, \uC774\uC9C1/\uC5F0\uBD09 \uD611\uC0C1 \uC720\uB9AC |\\n| \uC0AC\uC5C5\uC790 \uB4F1\uB85D \uC9C0\uC6D0 | \uBE44\uC0C1\uC8FC \uC624\uD53C\uC2A4 \uC784\uB300\uCC28 \uACC4\uC57D\uC11C \uBE44\uC6A9 6\uAC1C\uC6D4 \uC804\uC561 \uC9C0\uC6D0 |\\n\\n:::info\\n\uCDE8\uC5C5\uC9C0\uC6D0 \uAE30\uAC04: **\uC218\uAC15 6\uAC1C\uC6D4 + \uC218\uB8CC \uD6C4 6\uAC1C\uC6D4 = \uCD1D 1\uB144**\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC138\uB81D\uAC8C\uD2F0\uCEE4\uBBA4\uB2C8\uD2F0` `\uCDE8\uC5C5\uC0C1\uB2F4` `\uC11C\uB958\uCCA8\uC0AD` `\uB85C\uCF13\uB2E8` `\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC9C0\uC6D0`\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. QR \uCC0D\uACE0 **\uC2DC\uAC04 \uAE30\uB85D\uAE4C\uC9C0** \uD655\uC778\uD558\uC790 (\uCCB4\uD06C \uC644\uB8CC \uBBFF\uC9C0 \uB9D0 \uAC83)\\n2. **50% \uADDC\uCE59** \u2014 \uC808\uBC18 \uC774\uC0C1 \uC218\uAC15\uD574\uC57C \uC9C0\uAC01/\uC870\uD1F4\uB85C \uC778\uC815\\n3. \uC9C0\uAC01/\uC870\uD1F4/\uC678\uCD9C **\uB204\uC801 3\uD68C = \uACB0\uC11D 1\uD68C**\\n4. \uC9C8\uBCD1 \uACF5\uACB0\uC740 **\uC9C8\uBCD1\uCF54\uB4DC \uD3EC\uD568 \uC11C\uB958** \uD544\uC218, \uCD1D 12\uD68C \uD55C\uB3C4\\n5. \uBD80\uC815 \uCD9C\uACB0\uC740 **\uC989\uC2DC \uC81C\uC801** \u2014 \uD574\uC678 QR \uC808\uB300 \uAE08\uC9C0\\n6. \uBAA9\uD45C\uB294 **\uC218\uCE58\uD654** \u2014 \\"\uC774\uB825\uC11C \uC4F0\uAE30\\" \uB9D0\uACE0 \\"\uC218\uB8CC 2\uB2EC \uC804 \uCD08\uC548 \uC644\uC131\\""}]}}')}}]);